import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { Alignment, ButtonType, ButtonVariant, IconSize, Rel, Severity, Target } from '../../types';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';
import { FocusHelper } from '../../utils/focus-helper';
import { IconSizeHelper } from '../../utils/icon-size-helper';
import { verifyTarget } from '../../utils/link-helper';

/**
 * @nativeEvent click  - dispatched when button was clicked
 *
 * @slot default - default slot for the content of the button
 */
@Component({
  tag: 'groupui-button',
  styleUrl: 'button.scss',
  shadow: { delegatesFocus: true },
})
export class Button implements ComponentInterface {
  /**
   * sets the alignment in the button
   */
  @Prop({ reflect: true }) readonly alignment: Alignment;

  /**
   * sets focus automatically
   */
  // eslint-disable-next-line @stencil-community/reserved-member-names
  @Prop({ reflect: true }) readonly autofocus: boolean = false;

  /**
   * deactivates the button
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * optionally specifies the new filename for the downloaded file if a url is specified.
   */
  @Prop({ reflect: true }) readonly download: string;

  /**
   * sets the button to fullwidth
   */
  @Prop({ reflect: true }) readonly fullwidth: boolean = false;

  /**
   * icon name for an icon placed left to the text e.g. 'chevron-left-24'
   */
  @Prop({ reflect: true }) readonly iconLeft: string;

  /**
   * sets a custom icon source e.g. '...path/chevron-left-24.svg', overrides icon-left property if both are set
   */
  @Prop({ reflect: true }) readonly iconLeftSource: string;

  /**
   * hide text content and only show the icon (or both icons). requires an icon to be set
   */
  @Prop({ reflect: true }) readonly iconOnly: boolean = false;

  /**
   * icon name for an icon placed right to the text e.g. 'chevron-right-24'
   */
  @Prop({ reflect: true }) readonly iconRight: string;

  /**
   * sets a custom icon source e.g. '...path/chevron-right-24.svg', overrides icon-right property if both are set
   */
  @Prop({ reflect: true }) readonly iconRightSource: string;

  /**
   * activates an inverted presentation
   */
  @Prop({ reflect: true }) readonly inverted: boolean = false;

  /**
   * shows a loading indicator left to the text
   */
  @Prop({ reflect: true }) readonly loadingIndicatorLeft: boolean = false;

  /**
   * shows a loading indicator right to the text
   */
  @Prop({ reflect: true }) readonly loadingIndicatorRight: boolean = false;

  /**
   * in which relation is the linked URL to the current page
   */
  @Prop({ reflect: true }) readonly rel: Rel;

  /**
   * severity of the button
   */
  @Prop({ reflect: true }) readonly severity: Severity;

  /**
   * sets the button size
   */
  @Prop({ reflect: true }) readonly size: IconSize = 'm';

  /**
   * where to display the linked URL. On target 'none' no target attribute will be set.
   */
  @Prop({ reflect: true }) readonly target: Target = 'self';

  /**
   * type of the button.<br><br>
   * _Note:_ If the button is placed inside a form and the type is either 'reset' or 'submit' then it acts like a native
   * reset/submit-button. Keep in mind that at the moment no groupui component will actively listen for these form-events.
   * You have to listen for these events by yourself.
   */
  @Prop({ reflect: true }) readonly type: ButtonType = 'button';

  /**
   * URL that the hyperlink points to. Examples: https://www.volkswagen.de/ - tel:05361/12345 - mailto:john.doe@example.com - #anchor1<br><br>
   * _Note:_ Don't use this inside of a form together with type='submit' or type='reset'.
   **/
  @Prop({ reflect: true }) readonly url: string;

  /**
   * value of the button. This is the value that will be submitted if the button is placed inside a form.
   */
  @Prop({ reflect: true }) readonly value: string;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly variant: ButtonVariant = 'primary';

  @State() backupTabIndex: number;

  @State() tabIndex: number = 0;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false, composed: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  private ariaAttributes: AriaAttributes;

  @Watch('disabled')
  handleDisabledChanged() {
    try {
      if (this.disabled) {
        this.backupTabIndex = this.tabIndex;
      }
      this.tabIndex = FocusHelper.handleHostTabIndex(this.disabled, this.backupTabIndex);
      this.host.shadowRoot.getElementById('button').blur();
    } catch (event) {}
  }

  @Watch('size')
  onSizeChanged() {
    IconSizeHelper.setHeightAndWidth({
      host: this.host,
      size: this.size,
      selector: 'groupui-icon',
    });
  }

  @Listen('click', { capture: true })
  captureClick(event) {
    if (this.disabled) {
      event.stopPropagation();
    }
  }

  @Listen('click')
  onClick() {
    if (this.type === 'submit' || this.type === 'reset') {
      const form = this.host.parentElement;

      const hiddenButton = document.createElement('button');

      hiddenButton.type = this.type;
      hiddenButton.value = this.value;
      hiddenButton.style.display = 'none';

      form.appendChild(hiddenButton);
      hiddenButton.click();
      hiddenButton.remove();
    }
  }

  @Listen('focus')
  onFocus() {
    this.host.shadowRoot.querySelector('button').focus();
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Enter' || event.code === 'Space') {
      event.preventDefault();
    }
  }

  @Listen('keyup')
  onKeyUp(event: KeyboardEvent) {
    if (event.code === 'Enter' || event.code === 'Space') {
      if (this.url) {
        window.open(this.url, verifyTarget(this.target));
      } else {
        this.host.dispatchEvent(new window.Event('click', { bubbles: true }));
      }
    }
  }

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.backupTabIndex = Number(this.host.getAttribute('tabindex'));
    this.tabIndex = FocusHelper.handleHostTabIndex(this.disabled, this.backupTabIndex);
  }

  componentDidLoad() {
    IconSizeHelper.setHeightAndWidth({
      host: this.host,
      size: this.size,
      selector: 'groupui-icon',
    });
    this.autofocus && this.host.focus && this.host.focus();
    this.groupuiDidLoad.emit();
  }

  private getSlotAndIcon() {
    return [this.leftSlot(), this.textSlot(), this.rightSlot()].filter((slot) => slot != null);
  }

  private leftSlot() {
    const className = this.hasOnlyOneIcon() ? null : 'icon-left';

    if (this.loadingIndicatorLeft) {
      return this.loadingSlot(className);
    }

    if (this.hasLeftIcon()) {
      return this.leftIcon(className);
    }

    return null;
  }

  private textSlot() {
    if (this.iconOnly && this.hasIcon()) return null;
    return <slot />;
  }

  private rightSlot() {
    const className = this.hasOnlyOneIcon() ? null : 'icon-right';

    if (this.loadingIndicatorRight) {
      return this.loadingSlot(className);
    }

    if (this.hasRightIcon()) {
      return this.rightIcon(className);
    }

    return null;
  }

  private hasIcon() {
    return this.hasLeftIcon() || this.hasRightIcon();
  }

  private hasOnlyOneIcon(): boolean {
    if (!this.iconOnly) return false;
    if (this.hasLeftIcon() && this.hasRightIcon()) return false;
    return this.hasIcon();
  }

  private hasLeftIcon() {
    return !!this.iconLeft || !!this.iconLeftSource;
  }

  private hasRightIcon() {
    return !!this.iconRight || !!this.iconRightSource;
  }

  private leftIcon(className: string) {
    return this.iconSlot(className, this.iconLeft, this.iconLeftSource);
  }

  private rightIcon(className: string) {
    return this.iconSlot(className, this.iconRight, this.iconRightSource);
  }

  private iconSlot(className: string, iconName: string, iconSourceName: string) {
    return <groupui-icon class={className} name={iconName} src={iconSourceName} aria-hidden="true" />;
  }

  private loadingSlot(className: string) {
    return (
      <groupui-loading
        class={className}
        embedded
        no-track
        inverted={this.inverted !== (this.variant === 'primary')}
        size={this.size}
      ></groupui-loading>
    );
  }

  render() {
    return (
      <Host>
        {!this.url && (
          <button id="button" tabIndex={this.tabIndex} {...this.ariaAttributes} disabled={this.disabled}>
            {this.getSlotAndIcon()}
          </button>
        )}
        {this.url && (
          <a tabindex="-1" href={this.url} download={this.download} target={verifyTarget(this.target)} rel={this.rel}>
            <button id="button" tabIndex={this.tabIndex} role="link" disabled={this.disabled}>
              {this.getSlotAndIcon()}
            </button>
          </a>
        )}
      </Host>
    );
  }
}
